/* Finite State Machine for Alarm Management System */
states {
    Idle;
    LowPressureAlarm;
    HighPressureAlarmActive;
    HighPressureAlarmInactive;
    PIPTooHighAlarm;
    AlarmVisibleNoSound;
}

events {
    LowPressureTriggered;
    LowPressureReset;
    HighPressureBreathAboveThreshold;
    HighPressureBreathBelowThreshold;
    PIPTooHighTriggered;
    PIPTooHighReset;
    AlarmVisibilityToggle;
}

transitions {
    Idle --> LowPressureAlarm : LowPressureTriggered;
    LowPressureAlarm --> Idle : LowPressureReset;
    Idle --> HighPressureAlarmActive : HighPressureBreathAboveThreshold{ConsecutiveBreaths == 3};
    HighPressureAlarmActive --> HighPressureAlarmInactive : HighPressureBreathBelowThreshold;
    HighPressureAlarmInactive --> Idle : /* implicit */;
    Idle --> PIPTooHighAlarm : PIPTooHighTriggered;
    PIPTooHighAlarm --> Idle : PIPTooHighReset;
    Idle --> AlarmVisibleNoSound : AlarmVisibilityToggle{Visible == true, Sound == false};
    AlarmVisibleNoSound --> Idle : AlarmVisibilityToggle{Visible == false};
}

variables {
    ConsecutiveBreaths : integer = 0;
    PIPThreshold : real = /* commanded PIP value + 5 cm H2O */;
}

initial state Idle;

/* Guards */
guard LowPressureReset {
    /* True if pressure is above low pressure threshold */
    pressure > low_pressure_threshold;
}

guard HighPressureBreathAboveThreshold {
    /* True if current breath pressure > high pressure threshold */
    pressure > high_pressure_threshold;
}

guard HighPressureBreathBelowThreshold {
    /* True if current breath pressure <= high pressure threshold */
    pressure <= high_pressure_threshold;
}

guard PIPTooHighTriggered {
    /* True if current breath PIP > PIPThreshold */
    PIP > PIPThreshold;
}

/* Actions */
action LowPressureAlarm {
    log("Low pressure alarm ON");
    emit("Low pressure alarm sound");
}

action HighPressureAlarmActive {
    log("High pressure alarm ON");
    emit("High pressure alarm sound");
}

action HighPressureAlarmInactive {
    log("High pressure alarm OFF");
}

action PIPTooHighAlarm {
    log("PIP too high alarm ON");
    emit("PIP too high alarm sound");
}

action AlarmVisibleNoSound {
    log("Alarm visible, no sound");
}
